if(!$error&&($name===''||$slug===''||$cat<1))$error='Name, slug and category are required.';if(!$error){$slug=ianova_unique_slug($pdo,$slug,$id,$color,$size);}if(!$error){try{if($id){$s=$pdo->prepare('UPDATE products SET category_id=?,name=?,slug=?,description=?,price=?,original_price=?,emoji=?,bg_color=?,rating=?,review_count=?,stock=?,is_flash_deal=?,seller_name=?,image=?,subcategory=?,color=?,size=? WHERE id=?');$s->execute([$cat,$name,$slug,$desc,$price,$orig,$emoji,$bg,$rating,$reviews,$stock,$flash,$seller,$image,$sub,$color,$size,$id]);}else{$s=$pdo->prepare('INSERT INTO products(category_id,name,slug,description,price,original_price,emoji,bg_color,rating,review_count,stock,is_flash_deal,seller_name,image,subcategory,color,size) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$cat,$name,$slug,$desc,$price,$orig,$emoji,$bg,$rating,$reviews,$stock,$flash,$seller,$image,$sub,$color,$size]);}$back='products.php';header('Location: '.$back);exit;}catch(Throwable $e){$error='DEBUG: '.$e->getMessage();}}
